class Solution {
public:
    vector<int> bestTower(vector<vector<int>>& towers, vector<int>& center, int radius) {
        int bestQ = -1;
        vector<int> ans = {-1, -1};
        for (auto &t : towers) {
            int dist = abs(t[0] - center[0]) + abs(t[1] - center[1]);
            vector<int> pos = {t[0], t[1]};
            if (dist <= radius && (t[2] > bestQ || (t[2] == bestQ && pos < ans))) {
                bestQ = t[2]; ans = pos;
            }
        }
        return ans;
    }
};
